from src.nodes.base import BaseNode
from src.runtime.environment.environment_template_library import get_environment_template_library
import json

class Hou_Mcp_Environment_Blueprint(BaseNode):
    name = "hou_mcp_environment_blueprint"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("environment_name", "string", widget_type="text", default="western_room")
        self.add_output("blueprint_json", "string")
        self.add_output("atmosphere_profile", "string")
        self.add_output("construction_order_json", "string")
        self.add_output("is_valid", "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        env_name = (inputs.get("environment_name") or "").strip()
        if not env_name:
            self.log_error("No environment_name provided.")
            return {"blueprint_json": "{}", "atmosphere_profile": "", "construction_order_json": "[]", "is_valid": False, "exec_out": True}

        try:
            lib = get_environment_template_library()
            bp = lib.get_template(env_name)
            errors = bp.validate()
            is_valid = len(errors) == 0
            if errors:
                self.log_error(f"Blueprint validation errors: {errors}")
            else:
                self.log_info(f"Blueprint for '{env_name}': category={bp.environment_category}, atmosphere={bp.atmosphere_profile}")
            return {
                "blueprint_json":          json.dumps(bp.to_dict(), sort_keys=True, default=str),
                "atmosphere_profile":      bp.atmosphere_profile,
                "construction_order_json": json.dumps(bp.construction_order, default=str),
                "is_valid":                is_valid,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Blueprint fetch failed: {exc}")
            return {"blueprint_json": "{}", "atmosphere_profile": "", "construction_order_json": "[]", "is_valid": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Environment_Blueprint
